#!/usr/bin/env python3
"""Generate the C and Rust texture ABI from abi/texture.json; --check rejects drift."""
import argparse
import json
from pathlib import Path


def render(root):
    contract = json.loads((root / "abi/texture.json").read_text(encoding="utf-8"))
    c_types = {"i32": "int32_t", "i64": "int64_t", "u32": "uint32_t", "const_u8_ptr": "const uint8_t *"}
    rust_types = {"i32": "i32", "i64": "i64", "u32": "u32", "const_u8_ptr": "*const u8"}
    header = [
        "// Generated by scripts/generate-texture-abi.py; edit abi/texture.json.",
        "#ifndef KATAGLYPHIS_TEXTURE_ABI_H", "#define KATAGLYPHIS_TEXTURE_ABI_H", "#include <stdint.h>",
        "#if defined(_WIN32)", "#define KNT_EXPORT __declspec(dllexport)", "#else",
        '#define KNT_EXPORT __attribute__((visibility("default")))', "#endif",
        "#ifdef __cplusplus", 'extern "C" {', "#endif",
        f'#define KNT_API_VERSION {contract["version"]}',
    ]
    rust = [
        "// Generated by scripts/generate-texture-abi.py; edit abi/texture.json.",
        f'pub const API_VERSION: i32 = {contract["version"]};',
    ]
    for name, value in contract["result_codes"].items():
        header.append(f"#define KNT_{name} ({value})")
        rust.append(f"pub const {name}: i32 = {value};")
    for fn in contract["functions"]:
        c_args = ", ".join(f"{c_types[t]} {name}" for name, t in fn["arguments"]) or "void"
        r_args = ", ".join(rust_types[t] for _, t in fn["arguments"])
        header.append(f'KNT_EXPORT {c_types[fn["returns"]]} {fn["name"]}({c_args});')
        rust.append(f'pub type {fn["rust_type"]} = unsafe extern "C" fn({r_args}) -> {rust_types[fn["returns"]]};')
    header.extend(["#ifdef __cplusplus", "}", "#endif", "#endif", ""])
    rust.append("")
    return {root / "include/kataglyphis_texture_abi.h": "\n".join(header), root / "src/texture_abi.rs": "\n".join(rust)}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    different = []
    for path, expected in render(root).items():
        if args.check:
            if not path.is_file() or path.read_text(encoding="utf-8") != expected:
                different.append(str(path.relative_to(root)))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(expected, encoding="utf-8", newline="\n")
    if different:
        parser.exit(1, "Texture ABI is stale: " + ", ".join(different) + "\n")


if __name__ == "__main__":
    main()
